={
  "model": "deepseek-ocr",
  "prompt": "Analyze this invoice and extract all data as JSON. Return ONLY valid JSON with this exact structure:
{
  "vendor": { "name": "", "address": "", "tax_id": "" },
  "invoice": { "number": "", "date": "", "due_date": "" },
  "line_items": [{ "description": "", "quantity": 0, "unit_price": 0, "total": 0 }],
  "totals": { "net": 0, "tax_rate": 0, "tax_amount": 0, "gross": 0 }
}
No explanation, no markdown, just the JSON object.",
  "images": ["{{ $binary['Invoice File'].data }}"],
  "stream": false
}

parameters.jsCode:
const response = $input.first().json;

try {
  let content = response.response || '';
  content = content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    return {
      json: {
        success: true,
        invoice_data: parsed,
        processed_at: new Date().toISOString(),
        model: 'deepseek-ocr (local)'
      }
    };
  } else {
    throw new Error('No JSON found in response');
  }
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message,
      raw_response: response.response?.substring(0, 500)
    }
  };
}
